/// Fetch and install a module (its `install`).
let load (moduleName: string) : JS.Promise<unit> =
    match moduleName with
    | "Arrays" -> loadFnArrays ()
    | "Bonds" -> loadFnBonds ()
    | "Complex" -> loadFnComplex ()
    | "Database" -> loadFnDatabase ()
    | "Engineering" -> loadFnEngineering ()
    | "Financial" -> loadFnFinancial ()
    | "Information" -> loadFnInformation ()
    | "Math" -> loadFnMath ()
    | "Distributions" -> loadFnStatDist ()
    | "Statistical" -> loadFnStatistical ()
    | "Text" -> loadFnText ()
    | "Web" -> loadFnWeb ()
    | _ -> resolved ()
#endif
